154	function isHTTPURL(url: string): boolean {
155	  try {
156	    const parsed = new URL(url);
157	    return parsed.protocol === "http:" || parsed.protocol === "https:";
158	  } catch {
159	    return false;
160	  }
161	}
162	
163	export function useLinkMetadata(url: string, options?: { enabled?: boolean }) {
164	  const trimmedUrl = url.trim();
165	
166	  return useQuery({
167	    queryKey: memoKeys.linkMetadata(trimmedUrl),
168	    queryFn: async () => {
169	      const metadata = await memoServiceClient.getLinkMetadata({ url: trimmedUrl });
170	      return metadata;
171	    },
172	    enabled: (options?.enabled ?? true) && isHTTPURL(trimmedUrl),
173	    staleTime: 1000 * 60 * 60 * 24,
174	    gcTime: 1000 * 60 * 60 * 24,
175	  });
176	}
